// Input Iterator (Read Once)
// Supports: ==, !=, *deref (read), ++
template <typename T>
void consume_range(T begin, T end) {
    while (begin != end) {
        auto val = *begin; // Read Only
        ++begin;
    }
}
// Example: std::istream_iterator


// Output Iterator (Write Once)
// Supports: *deref (write), ++
template <typename T>
void write_range(T begin, T end) {
    *begin++ = 42; // Write Only
    *begin = 99;
}
// Example: std::ostream_iterator


